window.EP = {"name": "ch14", "label": "एपिसोड 14", "en": "Don't Answer If the Forest Calls Your Name", "duration": 1201.57, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 15.31, "text": "चैप्टर फ़ोर्टीन। डोंट आन्सर इफ़ द फ़ॉरेस्ट कॉल्स योर नेम"}, {"start": 15.86, "end": 18.02, "text": "डे फ़ोर्टीन। खलिया टॉप"}], "captions": [{"start": 19.57, "end": 26.29, "text": "चंपावत से मुनस्यारी तक लंबा रास्ता है: पिथौरागढ़, फिर घाटियों में उत्तर की तरफ़ ऊपर,", "who": "", "voice": "narrator", "diary": false}, {"start": 26.29, "end": 28.7, "text": "सड़क पहाड़ों से ऐसे चिपकी हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 28.7, "end": 32.38, "text": "जैसे कोई डरा हुआ बच्चा अपनी माँ के दुपट्टे से।", "who": "", "voice": "narrator", "diary": false}, {"start": 32.38, "end": 36.94, "text": "हम दोपहर को निकले, ठीक उसी पल, जब गौरव का वीडियो ऊपर गया,", "who": "", "voice": "narrator", "diary": false}, {"start": 36.94, "end": 40.31, "text": "आगे बसंती, और पीछे गौरव की सफ़ेद एस-यू-वी।", "who": "", "voice": "narrator", "diary": false}, {"start": 40.31, "end": 44.31, "text": "अँधेरा होने के बाद, हम खलिया ट्रेल के नीचे पहुँचे।", "who": "", "voice": "narrator", "diary": false}, {"start": 44.76, "end": 47.49, "text": "रोहन की एस-यू-वी ट्रेलहेड पर खड़ी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 47.49, "end": 47.94, "text": "ख़ाली।", "who": "", "voice": "narrator", "diary": false}, {"start": 47.94, "end": 48.68, "text": "इंजन ठंडा।", "who": "", "voice": "narrator", "diary": false}, {"start": 49.13, "end": 51.77, "text": "गौरव ने अपने फ़ोन पर जी-पी-एस लॉग चेक किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 51.97, "end": 53.35, "text": "दोपहर से ऊपर है।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 53.35, "end": 54.64, "text": "पाँच घंटे पहले।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 55.09, "end": 57.24, "text": "तो वो छानी तक पहुँच गया होगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 57.44, "end": 60.24, "text": "मैंने कहा, और मेरा जी मिचलाने लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 60.69, "end": 62.6, "text": "क्षितिज ने मेरी तरफ़ सिर हिलाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 63.05, "end": 63.74, "text": "नहीं, भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 63.74, "end": 65.73, "text": "वो एक छानी तक पहुँच गया होगा।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 65.93, "end": 67.99, "text": "उसने ऊपर अँधेरे की तरफ़ इशारा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 68.19, "end": 70.88, "text": "बुग्याल पे दर्जनों छानियाँ हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 70.88, "end": 73.13, "text": "पुरानी पत्थर की झोपड़ियाँ।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 73.13, "end": 77.03, "text": "मेरी पुरानी डायरी में बस इतना लिखा था: खलिया,", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 77.03, "end": 79.63, "text": "छानी, जोहार और नंदा दिखते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 79.63, "end": 81.89, "text": "हर छानी से जोहार दिखता है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 82.34, "end": 84.15, "text": "शाओनी ने भौंहें सिकोड़ीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 84.35, "end": 85.59, "text": "तो हम कैसे पहचानेंगे?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 86.04, "end": 87.96, "text": "क्षितिज ने अपनी कनपटी थपथपाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 88.41, "end": 90.72, "text": "धना जी ने एक बात और कही थी, दीदी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 90.72, "end": 91.84, "text": "मैंने लिखी नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 91.84, "end": 92.82, "text": "लिखना भूल गया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 92.82, "end": 93.52, "text": "पर याद है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 93.72, "end": 97.31, "text": "उसने शब्द बिल्कुल सही पकड़ने के लिए आँखें बंद कीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 97.51, "end": 99.74, "text": "ससुर जी ने छानी के बग़ल में,", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 99.74, "end": 103.1, "text": "आँछरियों के लिए, तीन पत्थर का घर बनाया था।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 103.1, "end": 105.33, "text": "ताकि वो चीज़ की रखवाली करें।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 105.78, "end": 106.5, "text": "तीन पत्थर।", "who": "", "voice": "narrator", "diary": false}, {"start": 106.5, "end": 107.66, "text": "वो छोटे-छोटे घर,", "who": "", "voice": "narrator", "diary": false}, {"start": 107.66, "end": 111.28, "text": "जो गाँव वाले बुग्यालों की परियों के लिए बनाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 111.28, "end": 115.11, "text": "कुमाऊँ का हर चरवाहा जानता होगा, कि इसका क्या मतलब है।", "who": "", "voice": "narrator", "diary": false}, {"start": 115.11, "end": 117.86, "text": "रोहन की चुराई हुई डायरी नहीं जानती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 118.31, "end": 119.52, "text": "डायरी सब कुछ नहीं है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 119.72, "end": 121.38, "text": "क्षितिज ने धीरे से कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 121.58, "end": 123.34, "text": "कुछ चीज़ें याद में होती हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 123.79, "end": 125.55, "text": "मैं बारह साल से पढ़ा रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 125.55, "end": 128.95, "text": "मैंने शिक्षा के बारे में इससे बेहतर वाक्य कभी नहीं सुना।", "who": "", "voice": "narrator", "diary": false}, {"start": 128.95, "end": 131.86, "text": "मैं इसे अपने ऑफ़िस के दरवाज़े पर लगाने वाला हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 132.31, "end": 136.92, "text": "कमांडेंट धामी के मैसेज में लिखा था: दो लोग भेज रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 136.92, "end": 137.84, "text": "पुराने लोग।", "who": "", "voice": "narrator", "diary": false}, {"start": 137.84, "end": 138.43, "text": "चुपचाप।", "who": "", "voice": "narrator", "diary": false}, {"start": 138.43, "end": 139.77, "text": "पुलिस सुबह आएगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 139.77, "end": 146.3, "text": "वो दोनों आदमी अँधेरे में ट्रेलहेड पर इंतज़ार कर रहे थे: अधेड़ उम्र के, ख़ामोश,", "who": "", "voice": "narrator", "diary": false}, {"start": 146.3, "end": 151.16, "text": "दरवाज़े की चौखट जैसे बने हुए, उस तरह की शांत चौकसी के साथ,", "who": "", "voice": "narrator", "diary": false}, {"start": 151.16, "end": 154.76, "text": "जो सिर्फ़ सरहद पर बीस साल बिताने से आती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 154.76, "end": 158.27, "text": "उन्होंने हमें सिर हिलाया, और कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 158.27, "end": 165.06, "text": "जब हम टॉर्च की रोशनी में ट्रेल पर ऊपर चले, वो हमारे पीछे चले, फिर थोड़ा साइड में,", "who": "", "voice": "narrator", "diary": false}, {"start": 165.06, "end": 167.9, "text": "और फिर मुझे वो दिखने ही बंद हो गए,", "who": "", "voice": "narrator", "diary": false}, {"start": 167.9, "end": 170.5, "text": "जो, मुझे लगता है, असल मक़सद था।", "who": "", "voice": "narrator", "diary": false}, {"start": 170.95, "end": 178.53, "text": "खलिया टॉप, बुराँस और बाँज के जंगल से होती हुई एक लंबी चढ़ाई है, जो अचानक पेड़ों के ऊपर,", "who": "", "voice": "narrator", "diary": false}, {"start": 178.53, "end": 181.92, "text": "लगभग साढ़े तीन हज़ार मीटर पर, एक विशाल,", "who": "", "voice": "narrator", "diary": false}, {"start": 181.92, "end": 185.14, "text": "लहराते, ऊँचे बुग्याल में खुल जाती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 185.14, "end": 191.24, "text": "दिन में, लोग कहते हैं, आप घाटी के पार पूरी पंचाचूली रेंज देख सकते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 191.24, "end": 195.24, "text": "पाँच सफ़ेद चोटियाँ, किसी हाथ की उँगलियों जैसी।", "who": "", "voice": "narrator", "diary": false}, {"start": 195.24, "end": 198.38, "text": "और दूर दक्षिण-पश्चिम में, नंदा देवी।", "who": "", "voice": "narrator", "diary": false}, {"start": 198.83, "end": 204.75, "text": "रात को, आपको तारे दिखते हैं, और पहाड़ियों की शक्लें, और एक आग।", "who": "", "voice": "narrator", "diary": false}, {"start": 205.2, "end": 207.58, "text": "चोटी के पास एक आग जल रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 207.58, "end": 218.05, "text": "चरवाहों का एक डेरा: पत्थर की एक नीची झोपड़ी, एक दीवार की आड़ में बाड़े में बंद कुछ बकरियाँ, और आग के पास बैठी एक बूढ़ी औरत,", "who": "", "voice": "narrator", "diary": false}, {"start": 218.05, "end": 220.95, "text": "काली पंखी और चाँदी की बालियों में,", "who": "", "voice": "narrator", "diary": false}, {"start": 220.95, "end": 225.63, "text": "जैसे वो इस किताब की शुरुआत से हमारा इंतज़ार कर रही हों।", "who": "", "voice": "narrator", "diary": false}, {"start": 226.08, "end": 227.73, "text": "उनका नाम भगुली अम्मा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 227.73, "end": 230.69, "text": "वो अठहत्तर साल की थीं, उन्होंने हमें बताया,", "who": "", "voice": "narrator", "diary": false}, {"start": 230.69, "end": 234.89, "text": "और उन्होंने अपनी ज़िंदगी की हर गर्मी इसी बुग्याल पर बिताई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 234.89, "end": 237.99, "text": "बर्फ़ से पहले, ये उनका यहाँ आख़िरी हफ़्ता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 238.44, "end": 239.93, "text": "उन्होंने हमें चाय दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 239.93, "end": 242.71, "text": "पहाड़ में, कोई न कोई हमेशा चाय देता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 242.71, "end": 247.05, "text": "और क्योंकि ये सीज़न की आख़िरी रात थी, और उनकी आग पर अजनबी थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 247.05, "end": 249.83, "text": "और वो एक पहाड़ी दादी थीं, और अँधेरा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 249.83, "end": 251.96, "text": "उन्होंने हमें कहानियाँ सुनाईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 252.41, "end": 254.79, "text": "उन्होंने हमें आँछरियों के बारे में बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 255.24, "end": 257.3, "text": "ऊँचे बुग्यालों की आत्माएँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 257.3, "end": 262.29, "text": "उन्होंने अपने चारों तरफ़ अँधेरी घास की तरफ़ हाथ फैलाते हुए कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 262.29, "end": 267.91, "text": "यहाँ ऊपर, बुग्यालों में, पेड़ों के ऊपर, जहाँ गर्मियों में फूल उगते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 267.91, "end": 271.0, "text": "और धुंध बिना चेतावनी के नीचे आ जाती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 271.0, "end": 273.22, "text": "कुछ कहते हैं, वो परियाँ हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 273.22, "end": 279.47, "text": "कुछ कहते हैं, वो उन लड़कियों की आत्माएँ हैं, जो जवानी में, शादी से पहले मर गईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 279.47, "end": 283.35, "text": "अपनी सारी इच्छाएँ अधूरी लिए, जो कभी आगे नहीं गईं,", "who": "", "voice": "narrator", "diary": false}, {"start": 283.35, "end": 286.76, "text": "बल्कि यहीं ऊँची जगहों पर रह गईं, नाचती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 287.21, "end": 289.57, "text": "उन्हें सुंदरता पसंद है।", "who": "", "voice": "narrator", "diary": false}, {"start": 289.57, "end": 291.73, "text": "उन्हें संगीत पसंद है।", "who": "", "voice": "narrator", "diary": false}, {"start": 291.73, "end": 294.19, "text": "उन्हें चटक रंग पसंद हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 294.64, "end": 297.28, "text": "उन्होंने सीधे शाओनी के स्कार्फ़ की तरफ़ देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 297.73, "end": 300.45, "text": "इसलिए, बेटी, ऊपर अकेले मत आना।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 300.45, "end": 302.17, "text": "लाल कपड़े मत पहनना।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 302.17, "end": 303.62, "text": "ज़ोर से मत गाना।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 303.62, "end": 304.88, "text": "सीटी मत बजाना।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 304.88, "end": 308.51, "text": "उनको जो पसंद आता है, उसे वो ले जाती हैं।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 308.96, "end": 313.01, "text": "शाओनी ने, बहुत धीरे से, अपना लाल स्कार्फ़ उतारा,", "who": "", "voice": "narrator", "diary": false}, {"start": 313.01, "end": 315.04, "text": "और अपने बैग में रख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 315.49, "end": 323.4, "text": "सौ साल पहले, जिन अंग्रेज़ अफ़सरों ने इन पहाड़ों के बारे में लिखा, उन्होंने भी यही मान्यता दर्ज की थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 323.4, "end": 329.36, "text": "भगुली अम्मा को ये जानकर ख़ुशी होगी: कि पहाड़ी आत्माओं को लाल रंग से चिढ़ है,", "who": "", "voice": "narrator", "diary": false}, {"start": 329.36, "end": 333.59, "text": "और गले में बँधा एक लाल धागा इंसान की रक्षा कर सकता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 333.59, "end": 336.57, "text": "पर लाल कपड़े उनका ध्यान खींच सकते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 336.57, "end": 339.47, "text": "हर घाटी इसे थोड़ा अलग ढंग से कहती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 339.47, "end": 340.65, "text": "हर दादी सही है।", "who": "", "voice": "narrator", "diary": false}, {"start": 341.1, "end": 343.89, "text": "फिर उन्होंने हमें जीतू बगड्वाल के बारे में बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 344.34, "end": 350.53, "text": "वो उन सभी गढ़वाली गाथा-नायकों में सबसे मशहूर है, जिनसे परियों को प्यार हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 350.53, "end": 354.25, "text": "उन्होंने कहा: टिहरी गढ़वाल का एक जवान चरवाहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 354.25, "end": 357.38, "text": "जो बाँसुरी इतनी ख़ूबसूरती से बजाता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 357.38, "end": 359.7, "text": "जितनी किसी ने कभी नहीं बजाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 359.7, "end": 365.56, "text": "एक दिन, अपनी बहन को घर लाने जाते हुए, वो खैट पर्वत की ढलानों से गुज़रा,", "who": "", "voice": "narrator", "diary": false}, {"start": 365.56, "end": 370.02, "text": "वो पहाड़, जिसे बूढ़े लोग आज भी परियों का देश कहते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 370.02, "end": 372.82, "text": "और वहाँ, अकेले, उसने बाँसुरी बजाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 372.82, "end": 375.14, "text": "और आँछरियों ने उसे सुन लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 375.14, "end": 377.78, "text": "उन्हें उसका संगीत इतना पसंद आया,", "who": "", "voice": "narrator", "diary": false}, {"start": 377.78, "end": 381.33, "text": "कि वो उसे हमेशा के लिए अपने लिए चाहने लगीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 382.03, "end": 383.36, "text": "तो वो उसे ले गईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 384.06, "end": 385.95, "text": "वो फिर कभी नहीं दिखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 385.95, "end": 392.35, "text": "लेकिन कुछ गाँवों में, आज भी, उसके नाम पर एक नाच होता है, बगड्वाल नृत्य,", "who": "", "voice": "narrator", "diary": false}, {"start": 392.35, "end": 395.77, "text": "और जब ढोल उसे बजाते हैं, लोग कहते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 395.77, "end": 400.54, "text": "जीतू एक रात के लिए वापस आता है, और उनके साथ नाचता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 400.99, "end": 403.76, "text": "भगुली अम्मा आग के पार मेरी तरफ़ मुस्कुराईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 403.96, "end": 406.24, "text": "इसलिए मैं बेसुरा गाती हूँ।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 406.69, "end": 410.84, "text": "वो ख़ुश होकर ठहाका मारकर हँसीं, और बकरियों ने ऊपर देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 411.29, "end": 414.67, "text": "मैं बेसुरा होने के लिए कभी इतना शुक्रगुज़ार नहीं हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 414.67, "end": 416.77, "text": "मैं चाहता हूँ, ये रिकॉर्ड पर रहे।", "who": "", "voice": "narrator", "diary": false}, {"start": 417.22, "end": 420.93, "text": "फिर, धीरे से, उन्होंने हमें वो कहानी सुनाई,", "who": "", "voice": "narrator", "diary": false}, {"start": 420.93, "end": 427.22, "text": "जो इस पूरे सफ़र में मैंने सुनी सबसे दुखभरी कहानी थी: काफल पक्षी की कहानी।", "who": "", "voice": "narrator", "diary": false}, {"start": 427.67, "end": 431.09, "text": "एक बार, उन्होंने कहा, एक ग़रीब विधवा थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 431.09, "end": 433.14, "text": "जिसकी सिर्फ़ एक बेटी थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 433.14, "end": 438.78, "text": "एक बसंत, माँ जंगल गई, और काफल की एक पूरी टोकरी इकट्ठा की, वो छोटे,", "who": "", "voice": "narrator", "diary": false}, {"start": 438.78, "end": 444.08, "text": "लाल, खट्टे-मीठे जंगली फल, जो चैत में इन पहाड़ियों पर पकते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 444.08, "end": 447.07, "text": "वो उन्हें बाज़ार में बेचने वाली थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 447.07, "end": 449.12, "text": "उनके पास बस यही पैसा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 449.12, "end": 454.41, "text": "उसने टोकरी अपनी बेटी के पास छोड़ी, और उससे कहा: एक भी मत खाना।", "who": "", "voice": "narrator", "diary": false}, {"start": 454.86, "end": 458.2, "text": "जब वो उस शाम वापस आई, टोकरी कम भरी हुई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 458.2, "end": 459.23, "text": "फल बैठ गए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 459.68, "end": 462.57, "text": "उसे लगा, उसकी बेटी ने उन्हें खा लिया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 462.57, "end": 464.38, "text": "और अपने ग़ुस्से, अपने डर,", "who": "", "voice": "narrator", "diary": false}, {"start": 464.38, "end": 467.2, "text": "और अपनी ग़रीबी में, उसने लड़की को मारा।", "who": "", "voice": "narrator", "diary": false}, {"start": 467.2, "end": 468.14, "text": "बहुत ज़ोर से।", "who": "", "voice": "narrator", "diary": false}, {"start": 468.84, "end": 469.7, "text": "बेटी मर गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 470.4, "end": 471.93, "text": "उस रात, ओस गिरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 471.93, "end": 477.47, "text": "और फल, जो दिन की गर्मी में बस सिकुड़ गए थे, फिर से फूल गए,", "who": "", "voice": "narrator", "diary": false}, {"start": 477.47, "end": 482.73, "text": "जब तक टोकरी फिर से भर नहीं गई, ठीक उतनी, जितनी पहले थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 482.73, "end": 484.35, "text": "एक भी कम नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 484.8, "end": 485.92, "text": "माँ समझ गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 485.92, "end": 487.84, "text": "और वो दुख से मर गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 488.29, "end": 490.06, "text": "दोनों पक्षी बन गईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 490.06, "end": 499.57, "text": "इन पहाड़ों में हर बसंत, जब काफल पकता है, आप एक पक्षी को पुकारते सुन सकते हैं, काफल पाको, मैंने न चाखो,", "who": "", "voice": "narrator", "diary": false}, {"start": 499.57, "end": 504.42, "text": "काफल पक गया, और मैंने चखा तक नहीं, और दूसरा, अंतहीन,", "who": "", "voice": "narrator", "diary": false}, {"start": 504.42, "end": 508.42, "text": "बहुत देर से, जवाब देता है: पुरै पुतै, पुरै।", "who": "", "voice": "narrator", "diary": false}, {"start": 508.42, "end": 509.64, "text": "सब हैं, बेटी।", "who": "", "voice": "narrator", "diary": false}, {"start": 509.64, "end": 510.29, "text": "सब हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 510.74, "end": 513.82, "text": "जब उन्होंने ख़त्म किया, किसी ने कुछ नहीं कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 513.82, "end": 516.01, "text": "क्षितिज ने लिखना बंद कर दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 516.01, "end": 517.66, "text": "शाओनी आग में देख रही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 517.66, "end": 521.91, "text": "गौरव ऊपर तारों को देख रहा था, और मुझे पूछने की ज़रूरत नहीं थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 521.91, "end": 524.1, "text": "कि वो किसके बारे में सोच रहा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 524.55, "end": 527.99, "text": "तब मुझे इन कहानियों के बारे में कुछ समझ आया,", "who": "", "voice": "narrator", "diary": false}, {"start": 527.99, "end": 532.05, "text": "जिसके चारों तरफ़ मैं चौदह दिनों से चक्कर काट रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 532.5, "end": 535.58, "text": "ये असल में आपको डराने के लिए नहीं हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 535.58, "end": 536.96, "text": "अकेले ऊपर मत जाओ।", "who": "", "voice": "narrator", "diary": false}, {"start": 536.96, "end": 538.26, "text": "रात को भटकना मत।", "who": "", "voice": "narrator", "diary": false}, {"start": 538.26, "end": 542.06, "text": "ऐसी आवाज़ का जवाब मत दो, जो तुम्हें दिखती नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 542.06, "end": 545.79, "text": "किसी सुंदर चीज़ के पीछे रास्ते से हटकर मत जाओ।", "who": "", "voice": "narrator", "diary": false}, {"start": 545.79, "end": 549.44, "text": "ग़ुस्से में हाथ मत उठाओ; तुम ग़लत हो सकते हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 549.44, "end": 551.3, "text": "हर एक कहानी एक नियम है।", "who": "", "voice": "narrator", "diary": false}, {"start": 551.3, "end": 556.73, "text": "पहाड़ों में तुम्हें ज़िंदा रखने का एक नियम, एक कहानी में लपेटा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 556.73, "end": 559.64, "text": "ताकि वो तुम्हें रात तीन बजे याद रहे,", "who": "", "voice": "narrator", "diary": false}, {"start": 559.64, "end": 561.91, "text": "जब तुम बाक़ी सब भूल चुके हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 562.36, "end": 566.49, "text": "ठीक आधी रात को, भगुली अम्मा खड़ी हुईं, और शुभ रात्रि कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 566.49, "end": 571.64, "text": "अपनी झोपड़ी के दरवाज़े पर, वो आग की तरफ़ वापस मुड़ीं, और हम सबसे बोलीं,", "who": "", "voice": "narrator", "diary": false}, {"start": 571.64, "end": 575.27, "text": "पर ज़्यादातर क्षितिज और मुझसे, जैसे उन्हें पता हो,", "who": "", "voice": "narrator", "diary": false}, {"start": 575.27, "end": 577.66, "text": "कि हम में से कौन दो जागते रहेंगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 578.11, "end": 578.83, "text": "एक बात।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 578.83, "end": 583.62, "text": "रात को, अगर जंगल तुम्हारा नाम ले, जवाब मत देना।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 583.62, "end": 585.15, "text": "पीछे मत मुड़ना।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 585.15, "end": 587.19, "text": "कौन है, भी मत पूछना।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 587.19, "end": 588.93, "text": "बस उसे बुलाने दो।", "who": "भगुली अम्मा", "voice": "bhaguli", "diary": false}, {"start": 589.38, "end": 591.13, "text": "फिर उन्होंने दरवाज़ा बंद कर लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 592.63, "end": 594.82, "text": "आगे क्या हुआ, आप जानते हैं, रीडर।", "who": "", "voice": "narrator", "diary": false}, {"start": 594.82, "end": 598.01, "text": "आपने इसे इस किताब की बिल्कुल शुरुआत में पढ़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 598.46, "end": 600.72, "text": "आग बुझकर नारंगी अंगारे रह गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 600.72, "end": 603.76, "text": "शाओनी टेंट में अपना हेडलैंप जलाए सो गई,", "who": "", "voice": "narrator", "diary": false}, {"start": 603.76, "end": 608.35, "text": "क्योंकि वो किसी चीज़ पर भरोसा नहीं करती, अँधेरे पर भी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 608.35, "end": 611.86, "text": "गब्बर एक चट्टान से टिककर बैठे-बैठे ऊँघने लगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 611.86, "end": 616.3, "text": "गौरव आग के पास पीठ के बल लेटा था, सीने पर एक थर्मल कैमरा,", "who": "", "voice": "narrator", "diary": false}, {"start": 616.3, "end": 619.49, "text": "जो वो लाया था, क्योंकि वो सब कुछ लाता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 619.49, "end": 625.95, "text": "और क्षितिज और मैं अंगारों के पास बैठे रहे, कंबलों में लिपटे, वो मेरे एक स्वेटर में,", "who": "", "voice": "narrator", "diary": false}, {"start": 625.95, "end": 629.23, "text": "जो मैंने उसे उधार नहीं दिया था, जागते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 629.23, "end": 632.42, "text": "उस बात की वजह से, जो बूढ़ी औरत ने कही थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 632.87, "end": 641.35, "text": "मैंने उस नोटबुक के पीछे से एक पन्ना फाड़ा, जो गौरव ने क्षितिज को दी थी, और पेंसिल से सब कुछ लिखना शुरू किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 641.35, "end": 645.67, "text": "क्योंकि अगर यहाँ ऊपर हमें कुछ हो जाता, तो मैं चाहता था,", "who": "", "voice": "narrator", "diary": false}, {"start": 645.67, "end": 650.38, "text": "कि किसी को, किसी दिन, पता चले, कि हम यहाँ तक कैसे पहुँचे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 651.08, "end": 653.4, "text": "लगभग तीन बजे, हवा रुक गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 654.1, "end": 659.33, "text": "और रात तीन बजकर बारह मिनट पर, आग की रोशनी के किनारे के उस पार से,", "who": "", "voice": "narrator", "diary": false}, {"start": 659.33, "end": 663.2, "text": "जहाँ बुग्याल जंगल में उतरता है, एक आवाज़ ने कहा:", "who": "", "voice": "narrator", "diary": false}, {"start": 663.9, "end": 665.0, "text": "क्षि…तिज…", "who": "", "voice": "forest", "diary": false}, {"start": 665.7, "end": 667.69, "text": "मैं सब फिर से नहीं लिखूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 667.69, "end": 669.9, "text": "आप जानते हैं, मैंने क्या सोचा।", "who": "", "voice": "narrator", "diary": false}, {"start": 669.9, "end": 673.29, "text": "आप जानते हैं, क्षितिज के होंठ कैसे दिख रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 673.29, "end": 675.8, "text": "आप जानते हैं, हमने जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 676.25, "end": 680.82, "text": "आप जानते हैं, कि कुछ देर बाद, आवाज़ ने क्षितिज कहना बंद कर दिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 680.82, "end": 682.75, "text": "और पार्थ कहना शुरू कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 683.2, "end": 688.22, "text": "जो आप नहीं जानते, वो ये है, कि उसके बाद क्या हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 688.67, "end": 697.7, "text": "गौरव उठकर बैठा, धीरे से, ख़ामोशी से, उस तरह, जैसे उसने चौदह महीनों में एक ऐसे आदमी का पीछा करते हुए हिलना सीखा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 697.7, "end": 701.11, "text": "जिसे पता नहीं चलना चाहिए था, कि वो वहाँ है,", "who": "", "voice": "narrator", "diary": false}, {"start": 701.11, "end": 705.39, "text": "थर्मल कैमरा उठाया, और उसे पेड़ों की कतार की तरफ़ किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 705.84, "end": 711.83, "text": "छोटी सी स्क्रीन पर, सब कुछ गहरा नीला और काला था: ठंडी चट्टानें,", "who": "", "voice": "narrator", "diary": false}, {"start": 711.83, "end": 713.73, "text": "ठंडी घास, ठंडे पेड़।", "who": "", "voice": "narrator", "diary": false}, {"start": 713.73, "end": 717.63, "text": "और दो पेड़ों के बीच, लगभग चालीस मीटर दूर,", "who": "", "voice": "narrator", "diary": false}, {"start": 717.63, "end": 722.47, "text": "उकड़ूँ बैठी, एक बड़ी, चमकीली, नारंगी-पीली आकृति थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 723.17, "end": 723.92, "text": "एक आदमी।", "who": "", "voice": "narrator", "diary": false}, {"start": 723.92, "end": 725.59, "text": "एक बहुत बड़ा आदमी।", "who": "", "voice": "narrator", "diary": false}, {"start": 726.29, "end": 729.46, "text": "गौरव ने ज़ूम किया, और स्क्रीन को झुकाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 729.46, "end": 731.75, "text": "ताकि क्षितिज और मैं देख सकें।", "who": "", "voice": "narrator", "diary": false}, {"start": 731.75, "end": 733.65, "text": "आकृति ने अपना वज़न बदला।", "who": "", "voice": "narrator", "diary": false}, {"start": 733.65, "end": 737.45, "text": "उसका एक पैर, मैंने देखा, चमकीला पीला चमक रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 737.45, "end": 740.69, "text": "दूसरा, कहीं ज़्यादा गहरा, ठंडा नारंगी था।", "who": "", "voice": "narrator", "diary": false}, {"start": 741.39, "end": 742.29, "text": "एक जूता।", "who": "", "voice": "narrator", "diary": false}, {"start": 742.29, "end": 743.3, "text": "एक मोज़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 744.0, "end": 744.56, "text": "भल्ला।", "who": "गौरव", "voice": "gaurav", "diary": false}, {"start": 744.76, "end": 746.04, "text": "गौरव ने साँस में कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 746.49, "end": 747.55, "text": "कोई परी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 747.55, "end": 748.77, "text": "कोई ख़बीस नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 748.77, "end": 751.45, "text": "ऊँचे बुग्यालों की कोई आत्मा नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 751.45, "end": 758.44, "text": "एक आदमी, जिसने लोहाघाट में एक जूता खो दिया था, रात तीन बजे जंगल में उकड़ूँ बैठा, लंबी,", "who": "", "voice": "narrator", "diary": false}, {"start": 758.44, "end": 761.36, "text": "नरम आवाज़ में हमारे नाम पुकारता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 761.36, "end": 765.91, "text": "हम में से किसी एक को आग से दूर ललचाने की कोशिश करता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 765.91, "end": 767.13, "text": "मुझे एहसास हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 767.13, "end": 772.25, "text": "वो घंटों से पेड़ों में से भगुली अम्मा की कहानियाँ सुन रहा होगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 772.25, "end": 774.12, "text": "उसे पुराना नियम पता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 774.12, "end": 777.37, "text": "वो उसे हमारे ख़िलाफ़ इस्तेमाल कर रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 777.82, "end": 780.59, "text": "और पुराने नियम ने ही हमें बचाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 780.59, "end": 783.53, "text": "क्योंकि किसी ने जवाब नहीं दिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 783.98, "end": 787.17, "text": "आवाज़ फिर आई, अब ज़्यादा पास, बेसब्र।", "who": "", "voice": "narrator", "diary": false}, {"start": 787.87, "end": 788.67, "text": "पा…र्थ…", "who": "", "voice": "forest", "diary": false}, {"start": 789.37, "end": 794.51, "text": "आकृति पेड़ों की कतार के साथ-साथ हमारी तरफ़ बढ़ने लगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 794.51, "end": 795.19, "text": "और पास।", "who": "", "voice": "narrator", "diary": false}, {"start": 795.19, "end": 796.06, "text": "तीस मीटर।", "who": "", "voice": "narrator", "diary": false}, {"start": 796.06, "end": 796.45, "text": "बीस।", "who": "", "voice": "narrator", "diary": false}, {"start": 797.15, "end": 798.59, "text": "और फिर मेरा फ़ोन बजा।", "who": "", "voice": "narrator", "diary": false}, {"start": 799.29, "end": 805.15, "text": "मुझे ज़रूरत है, कि आप रात तीन बजकर चौदह मिनट पर, पूरी ख़ामोशी में,", "who": "", "voice": "narrator", "diary": false}, {"start": 805.15, "end": 810.57, "text": "बिना हवा के, एक ऊँचे हिमालयी बुग्याल की ध्वनि-व्यवस्था समझें।", "who": "", "voice": "narrator", "diary": false}, {"start": 811.02, "end": 813.54, "text": "वहाँ बजता फ़ोन, फ़ोन नहीं होता।", "who": "", "voice": "narrator", "diary": false}, {"start": 813.54, "end": 815.97, "text": "वो हवाई हमले का सायरन होता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 816.42, "end": 822.78, "text": "मेरी रिंगटोन, मुझे माफ़ कीजिए, मुझे इस पर गर्व नहीं है, मेरे स्टूडेंट्स ने लगाई थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 822.78, "end": 826.84, "text": "पूरे वॉल्यूम पर एक गढ़वाली शादी के गाने की शुरुआत है।", "who": "", "voice": "narrator", "diary": false}, {"start": 826.84, "end": 829.14, "text": "वो खलिया टॉप के पार ऐसे गूँजी,", "who": "", "voice": "narrator", "diary": false}, {"start": 829.14, "end": 832.89, "text": "जैसे कोई बारात स्वर्ग के दरवाज़े पर पहुँच रही हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 833.34, "end": 834.66, "text": "मैं फ़ोन के लिए झपटा।", "who": "", "voice": "narrator", "diary": false}, {"start": 834.66, "end": 837.29, "text": "मेरी जमी हुई उँगलियाँ डिक्लाइन से चूक गईं।", "who": "", "voice": "narrator", "diary": false}, {"start": 837.29, "end": 838.86, "text": "उन्होंने स्पीकर दबा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 839.31, "end": 845.77, "text": "और पूरे सोते हुए बुग्याल के पार, जंगल में, अँधेरे में, एक ऐसे वॉल्यूम पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 845.77, "end": 849.84, "text": "जो आज तक किसी देवता या भूत ने हासिल नहीं किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 849.84, "end": 851.87, "text": "मेरी मम्मी की आवाज़ आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 852.57, "end": 853.09, "text": "पार्थ!", "who": "मम्मी", "voice": "mummyphone", "diary": false}, {"start": 853.09, "end": 854.21, "text": "स्वेटर पहना?!", "who": "मम्मी", "voice": "mummyphone", "diary": false}, {"start": 854.91, "end": 859.92, "text": "पेड़ों के किनारे पर, गौरव की स्क्रीन पर वो बड़ी नारंगी आकृति,", "who": "", "voice": "narrator", "diary": false}, {"start": 859.92, "end": 862.06, "text": "लगभग एक मीटर हवा में उछली।", "who": "", "voice": "narrator", "diary": false}, {"start": 862.51, "end": 866.99, "text": "भल्ला ने चौदह दिन, घाटों, लाल रोशनियों, चलती हुई शॉलों,", "who": "", "voice": "narrator", "diary": false}, {"start": 866.99, "end": 870.17, "text": "और गाय की घंटियों से डरते हुए बिताए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 870.17, "end": 877.75, "text": "उसने पिछले छह घंटे भगुली अम्मा को बुग्याल की उन आत्माओं के बारे में बताते सुनते हुए बिताए थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 877.75, "end": 881.0, "text": "जो, जिसे पसंद करती हैं, उसे ले जाती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 881.0, "end": 886.79, "text": "और अब, आधी रात को, जंगल ने ख़ुद, एक औरत की आवाज़ में, उसे जवाब दिया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 886.79, "end": 891.1, "text": "विशाल, कहीं से भी नहीं, स्वेटर के बारे में पूछते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 891.8, "end": 892.6, "text": "वो भागा।", "who": "", "voice": "narrator", "diary": false}, {"start": 893.3, "end": 901.26, "text": "वो ढलान से नीचे भागा, सीधा पेड़ों में, एक जूते में, बुराँस को तोड़ता हुआ, कुछ ऐसा चिल्लाता हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 901.26, "end": 904.95, "text": "जो मैं छापूँगा नहीं, क्योंकि ये किताब बच्चे,", "who": "", "voice": "narrator", "diary": false}, {"start": 904.95, "end": 907.38, "text": "और मेरे एच-ओ-डी पढ़ सकते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 907.38, "end": 912.07, "text": "और वो ठीक उसी दिशा में भागा, जहाँ, मुझे बाद में पता चला,", "who": "", "voice": "narrator", "diary": false}, {"start": 912.07, "end": 915.0, "text": "कमांडेंट धामी के दोनों ख़ामोश आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 915.0, "end": 918.69, "text": "पूरी रात अँधेरे में लेटे, इंतज़ार कर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 919.14, "end": 921.93, "text": "हमने धड़ाम की आवाज़ सुनी।", "who": "", "voice": "narrator", "diary": false}, {"start": 921.93, "end": 922.82, "text": "एक चीख़।", "who": "", "voice": "narrator", "diary": false}, {"start": 922.82, "end": 925.28, "text": "एक छोटी, तेज़ हाथापाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 925.28, "end": 926.62, "text": "फिर ख़ामोशी।", "who": "", "voice": "narrator", "diary": false}, {"start": 927.07, "end": 930.52, "text": "फिर ख़ामोश आदमियों में से एक की आवाज़,", "who": "", "voice": "narrator", "diary": false}, {"start": 930.52, "end": 932.89, "text": "शांत, ढलान पर ऊपर आती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 933.34, "end": 933.94, "text": "मिल गया।", "who": "", "voice": "local", "diary": false}, {"start": 934.39, "end": 934.75, "text": "पार्थ?", "who": "मम्मी", "voice": "mummyphone", "diary": false}, {"start": 934.75, "end": 935.12, "text": "पार्थ?", "who": "मम्मी", "voice": "mummyphone", "diary": false}, {"start": 935.12, "end": 936.36, "text": "क्या हो रहा है वहाँ?", "who": "मम्मी", "voice": "mummyphone", "diary": false}, {"start": 936.36, "end": 937.47, "text": "कौन चिल्ला रहा है?", "who": "मम्मी", "voice": "mummyphone", "diary": false}, {"start": 937.92, "end": 939.33, "text": "मैंने फ़ोन उठाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 939.33, "end": 944.39, "text": "मेरे हाथ इतनी ज़ोर से काँप रहे थे, कि वो लगभग आग में गिर गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 944.84, "end": 945.22, "text": "मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 945.42, "end": 945.97, "text": "मैंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 946.17, "end": 948.0, "text": "आप… आप तीन बजे क्यों फ़ोन कर रही हो?", "who": "", "voice": "narrator", "diary": false}, {"start": 948.45, "end": 949.32, "text": "सपना आया।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 949.52, "end": 950.54, "text": "मेरी मम्मी ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 950.74, "end": 951.95, "text": "तुम ठंड में बैठे हो।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 951.95, "end": 952.68, "text": "काँप रहे हो।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 952.68, "end": 954.68, "text": "तो मैंने सोचा, फ़ोन करके पूछ लूँ।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 954.88, "end": 956.46, "text": "एक शक भरा पॉज़।", "who": "", "voice": "narrator", "diary": false}, {"start": 956.66, "end": 957.46, "text": "स्वेटर पहना?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 957.91, "end": 959.63, "text": "मैंने क्षितिज को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 959.63, "end": 963.38, "text": "क्षितिज इतनी ज़ोर से हँस रहा था, कि गिर पड़ा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 963.38, "end": 969.1, "text": "शाओनी अपने हेडलैंप के साथ टेंट से बाहर आ गई थी, उसका चेहरा डर से उलझन तक,", "who": "", "voice": "narrator", "diary": false}, {"start": 969.1, "end": 972.69, "text": "और फिर किसी हिस्टीरिया जैसी चीज़ तक जा रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 972.69, "end": 974.73, "text": "गब्बर जागे हुए घूर रहे थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 974.73, "end": 979.58, "text": "गौरव थर्मल कैमरा पकड़े, एक साथ रो भी रहा था, और हँस भी रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 980.03, "end": 980.41, "text": "मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 980.61, "end": 981.4, "text": "मैंने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 981.6, "end": 983.51, "text": "आपने अभी एक क्रिमिनल पकड़वा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 983.96, "end": 986.27, "text": "वडोदरा से एक लंबी ख़ामोशी आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 986.72, "end": 987.26, "text": "अच्छा।", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 987.46, "end": 988.48, "text": "मेरी मम्मी ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 988.68, "end": 989.47, "text": "स्वेटर पहना?", "who": "मम्मी", "voice": "mummy", "diary": false}, {"start": 989.92, "end": 991.56, "text": "तीन, मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 991.56, "end": 992.16, "text": "तीन।", "who": "", "voice": "narrator", "diary": false}, {"start": 993.66, "end": 995.94, "text": "उसके बाद कोई नहीं सोया।", "who": "", "voice": "narrator", "diary": false}, {"start": 995.94, "end": 1003.96, "text": "हम फिर से जलाई गई आग के पास बैठे रहे, और आसमान को काले से धूसर, और फिर सबसे फीके,", "who": "", "voice": "narrator", "diary": false}, {"start": 1003.96, "end": 1007.82, "text": "सबसे ठंडे नीले रंग में बदलते देखते रहे,", "who": "", "voice": "narrator", "diary": false}, {"start": 1007.82, "end": 1010.69, "text": "और रोशनी का इंतज़ार करते रहे।", "who": "", "voice": "narrator", "diary": false}, {"start": 1011.14, "end": 1016.97, "text": "जब वो आई, तो एक साथ आई: सुनहरी, पूरब की धारों के ऊपर से बहती हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 1016.97, "end": 1023.96, "text": "और घाटी के पार पंचाचूली की चोटियों को पाँच विशाल मोमबत्तियों की तरह जलाती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1023.96, "end": 1027.45, "text": "दूर दक्षिण-पश्चिम में, गुलाबी और सफ़ेद,", "who": "", "voice": "narrator", "diary": false}, {"start": 1027.45, "end": 1032.2, "text": "और नामुमकिन ऊँचाई पर, नंदा देवी ने सूरज को पकड़ लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1032.65, "end": 1037.17, "text": "और बुग्याल के दूसरी तरफ़, पाले से ढकी घास की एक लंबी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1037.17, "end": 1041.76, "text": "मुड़ी हुई ढलान के पार, शाओनी ने उन्हें सबसे पहले देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 1041.76, "end": 1044.83, "text": "उसने मेरी बाँह पकड़ी, और इशारा किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1045.28, "end": 1048.52, "text": "आकृतियों की एक कतार, तेज़ी से चलती हुई।", "who": "", "voice": "narrator", "diary": false}, {"start": 1048.52, "end": 1053.76, "text": "पाँच या छह, हेडलैंप अब भी जलाए, हालाँकि अब उनकी ज़रूरत नहीं थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 1053.76, "end": 1059.5, "text": "बुग्याल के एक उभार पर बनी एक अकेली पत्थर की झोपड़ी की तरफ़ बढ़ती हुई,", "who": "", "voice": "narrator", "diary": false}, {"start": 1059.5, "end": 1064.32, "text": "जो उत्तर की गहरी घाटी की तरफ़ देखती थी: गोरी गंगा की घाटी,", "who": "", "voice": "narrator", "diary": false}, {"start": 1064.32, "end": 1066.23, "text": "जोहार का पुराना रास्ता।", "who": "", "voice": "narrator", "diary": false}, {"start": 1066.68, "end": 1069.31, "text": "उनके आगे, एक लंबे, गहरे कोट में,", "who": "", "voice": "narrator", "diary": false}, {"start": 1069.31, "end": 1073.16, "text": "तेज़ी से चलता हुआ, पीछे मुड़कर देखे बिना: रोहन।", "who": "", "voice": "narrator", "diary": false}, {"start": 1073.61, "end": 1080.23, "text": "और झोपड़ी के बग़ल में, सुबह की शुरुआती रोशनी में छोटे और धूसर, लगभग अदृश्य,", "who": "", "voice": "narrator", "diary": false}, {"start": 1080.23, "end": 1085.53, "text": "जब तक आपको पता न हो, कि आप क्या ढूँढ रहे हैं, तीन गोल पत्थर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1086.23, "end": 1088.14, "text": "परियों के लिए एक घर।", "who": "", "voice": "narrator", "diary": false}, {"start": 1088.84, "end": 1090.27, "text": "उसने उसे ढूँढ लिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 1090.97, "end": 1092.71, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1092.71, "end": 1094.72, "text": "डे फ़ोर्टीन, खलिया टॉप।", "who": "", "voice": "narrator", "diary": true}, {"start": 1095.17, "end": 1098.09, "text": "आँछरियाँ: अकेले मत जाओ, सीटी मत बजाओ,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1098.09, "end": 1100.3, "text": "ज़ोर से मत गाओ, लाल मत पहनो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1100.3, "end": 1102.67, "text": "दीदी ने अपना स्कार्फ़ रख दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1103.12, "end": 1105.71, "text": "जीतू बगड्वाल: एक बाँसुरी वाला,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1105.71, "end": 1109.5, "text": "जिसे आँछरियों ने बहुत प्यार किया, और ले गईं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1109.5, "end": 1111.75, "text": "उसके नाम पर बगड्वाल नृत्य।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1111.75, "end": 1114.94, "text": "भगुली अम्मा जानबूझकर बेसुरा गाती हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1114.94, "end": 1117.62, "text": "पार्थ भाई भी, पर जानबूझकर नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1118.07, "end": 1122.8, "text": "काफल पक्षी: काफल पाको, मैंने न चाखो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1122.8, "end": 1124.9, "text": "पुरै पुतै, पुरै।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1124.9, "end": 1129.63, "text": "जब वो सुना रही थीं, मैंने नहीं लिखा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1129.63, "end": 1131.87, "text": "मैं नहीं लिख सका।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1132.32, "end": 1134.49, "text": "सारी कहानियाँ नियम हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1134.49, "end": 1137.88, "text": "ज़िंदा रहने के नियम, पोशाक पहने हुए।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1138.33, "end": 1143.88, "text": "रात तीन बजकर बारह मिनट: जंगल ने मेरा नाम लिया, फिर पार्थ भाई का।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1143.88, "end": 1145.61, "text": "हमने जवाब नहीं दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1145.61, "end": 1146.65, "text": "वो भल्ला था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1146.65, "end": 1148.47, "text": "एक जूता, थर्मल कैमरा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1148.47, "end": 1152.88, "text": "वो पुराने नियम को हमारे ख़िलाफ़ इस्तेमाल कर रहा था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1152.88, "end": 1154.62, "text": "पुराना नियम जीत गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1155.07, "end": 1158.53, "text": "मम्मी आंटी ने तीन बजकर चौदह मिनट पर, स्पीकर पर फ़ोन किया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1158.53, "end": 1159.68, "text": "पार्थ, स्वेटर पहना?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1159.68, "end": 1162.66, "text": "भल्ला भागकर कमांडेंट धामी के आदमियों में जा गिरा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1162.66, "end": 1163.27, "text": "पकड़ा गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1163.27, "end": 1167.16, "text": "मम्मी आंटी ने अब इंस्पेक्टर बिष्ट से ज़्यादा क्रिमिनल पकड़े हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1167.61, "end": 1173.0, "text": "भोर: आर. और पाँच आदमी, एक अकेली पत्थर की झोपड़ी की तरफ़।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1173.0, "end": 1175.31, "text": "उसके बग़ल में तीन पत्थर।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1175.31, "end": 1176.75, "text": "उसने ढूँढ लिया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1176.75, "end": 1177.91, "text": "मुझे याद था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1177.91, "end": 1179.64, "text": "वो पहले पहुँच गया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1180.09, "end": 1181.5, "text": "डायरी सब कुछ नहीं है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1181.5, "end": 1183.38, "text": "कुछ चीज़ें याद में होती हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1183.38, "end": 1187.4, "text": "पार्थ भाई कहते हैं, वो इसे अपने ऑफ़िस के दरवाज़े पर लगाएँगे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1187.4, "end": 1189.35, "text": "मैंने कहा, मुझे क्रेडिट देना।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1189.35, "end": 1190.69, "text": "उन्होंने कहा, देंगे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1190.69, "end": 1192.57, "text": "लिख रहा हूँ, ताकि देना पड़े।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 18.37, "bed": "drive"}, {"at": 43.56, "bed": "suspense"}, {"at": 87.21, "bed": "discovery"}, {"at": 131.11, "bed": "vigil"}, {"at": 169.75, "bed": "stars"}, {"at": 204.0, "bed": "campfire"}, {"at": 251.21, "bed": "night"}, {"at": 339.9, "bed": "legend"}, {"at": 399.79, "bed": "campfire"}, {"at": 416.02, "bed": "tender"}, {"at": 523.35, "bed": "bench"}, {"at": 561.16, "bed": "night"}, {"at": 591.43, "bed": "fog"}, {"at": 649.88, "bed": "stillness"}, {"at": 664.5, "bed": "fog"}, {"at": 687.47, "bed": "suspense"}, {"at": 782.78, "bed": "threat"}, {"at": 795.95, "bed": "stillness"}, {"at": 815.22, "bed": "caper"}, {"at": 890.6, "bed": "chase"}, {"at": 925.87, "bed": "stillness"}, {"at": 933.19, "bed": "caper"}, {"at": 992.46, "bed": "dawn"}, {"at": 1009.94, "bed": "summit"}, {"at": 1031.45, "bed": "threat"}, {"at": 1089.77, "bed": "diary"}, {"at": 1089.77, "bed": "diary"}], "hits": [{"at": 123.64, "fx": "sting_light"}, {"at": 381.88, "fx": "flute"}, {"at": 406.54, "fx": "firepop"}, {"at": 488.14, "fx": "kafal"}, {"at": 589.23, "fx": "door"}, {"at": 632.72, "fx": "page"}, {"at": 683.05, "fx": "sting_light"}, {"at": 741.24, "fx": "sting"}, {"at": 797.0, "fx": "silence"}, {"at": 816.27, "fx": "ringtone"}, {"at": 854.76, "fx": "crash"}, {"at": 918.99, "fx": "thud"}, {"at": 1088.69, "fx": "sting"}, {"at": 1138.18, "fx": "sting_light"}, {"at": 1167.46, "fx": "sting"}], "next": {"label": "एपिसोड 15", "en": "Some Questions the Mountains Keep", "hook": "खलिया की एक झोपड़ी। लकड़ी का एक डब्बा। और वो सवाल, जो पहाड़ रख लेते हैं।"}};
